insert into public.levels(id,ord,title,src) values('s1',1,'Introduction à la blockchain et au Web3','Session 1 · support PDF et vidéos') on conflict(id) do update set ord=excluded.ord,title=excluded.title,src=excluded.src;
insert into public.questions values('s1',0,'Qu''est-ce qu''une blockchain, au sens le plus simple ?','["Un registre partagé où l''on ajoute des blocs sans pouvoir réécrire les anciens","Une base de données gérée par une seule banque","Un logiciel de minage","Un type de cryptomonnaie"]'::jsonb,0,'C''est un registre distribué, en ajout seul : chaque participant en garde une copie et on n''ajoute que de nouveaux blocs.');
insert into public.questions values('s1',1,'Que se passe-t-il si on change une seule lettre dans l''entrée d''une fonction de hachage ?','["Le hash change d''une lettre","Le hash reste identique","Le hash devient complètement différent","La fonction renvoie une erreur"]'::jsonb,2,'C''est l''effet avalanche : une infime modification donne une empreinte totalement différente. C''est ce qui rend toute falsification visible.');
insert into public.questions values('s1',2,'Qu''est-ce qui relie un bloc au précédent ?','["La date du bloc","Le hash du bloc précédent, inscrit dans son en-tête","L''adresse du mineur","Le montant total des transactions"]'::jsonb,1,'Chaque bloc contient l''empreinte du bloc d''avant. Modifier un bloc casse tous les liens qui suivent.');
insert into public.questions values('s1',3,'Pourquoi est-il si difficile de modifier une transaction ancienne sur Bitcoin ?','["Elle est chiffrée par la police","Il faudrait refaire le travail de ce bloc et de tous les suivants, plus vite que le reste du réseau","Les anciennes transactions sont supprimées","Seul Satoshi peut le faire"]'::jsonb,1,'Il faudrait recalculer la preuve de travail de toute la chaîne qui suit et dépasser la majorité de la puissance de calcul.');
insert into public.questions values('s1',4,'Quel problème la blockchain a-t-elle résolu pour la monnaie numérique ?','["La double dépense sans tiers de confiance","L''inflation","Le stockage des photos","La vitesse d''Internet"]'::jsonb,0,'Un fichier numérique se copie. Sans banque, il fallait empêcher de dépenser deux fois la même unité : le registre partagé et le consensus le permettent.');
insert into public.questions values('s1',5,'Quel est le rôle d''un nœud ?','["Imprimer des billets","Garder une copie du registre et vérifier les règles","Fixer le prix","Stocker les mots de passe"]'::jsonb,1,'Un nœud vérifie chaque bloc et chaque transaction selon les règles du protocole et refuse ce qui est invalide.');
insert into public.questions values('s1',6,'Avec quelle clé signe-t-on une transaction ?','["La clé publique","La clé privée","L''adresse","Le hash du bloc"]'::jsonb,1,'La clé privée signe ; la clé publique permet à tout le monde de vérifier la signature sans connaître la clé privée.');
insert into public.questions values('s1',7,'Que prouve une signature numérique valide ?','["Que la transaction est gratuite","Que le détenteur de la clé privée a autorisé la transaction et qu''elle n''a pas été modifiée","L''identité civile de l''expéditeur","Que le bloc est miné"]'::jsonb,1,'Elle prouve l''autorisation et l''intégrité du message, pas l''identité réelle de la personne.');
insert into public.questions values('s1',8,'Comment résume-t-on souvent l''évolution Web1 → Web2 → Web3 ?','["Lire → Lire et écrire → Lire, écrire et posséder","Texte → Images → Vidéo","Ordinateur → Mobile → Montre","Gratuit → Payant → Gratuit"]'::jsonb,0,'Le Web3 ajoute la propriété : l''utilisateur détient ses actifs et ses données via ses clés.');
insert into public.questions values('s1',9,'En preuve de travail, comment un mineur gagne-t-il le droit d''ajouter un bloc ?','["Par tirage au sort parmi les plus riches","En trouvant par essais successifs un hash inférieur à une cible","Par vote des utilisateurs","En payant une licence"]'::jsonb,1,'Il essaie des milliards de valeurs (le nonce) jusqu''à obtenir un hash sous la cible fixée par la difficulté.');
insert into public.questions values('s1',10,'En preuve d''enjeu, qu''est-ce qui sécurise le réseau ?','["L''électricité consommée","Les jetons que les validateurs engagent et peuvent perdre s''ils trichent","Les serveurs d''une entreprise","Les mots de passe"]'::jsonb,1,'Les validateurs mettent leurs jetons en jeu. Tricher coûte cher, sans dépense énergétique massive.');
insert into public.questions values('s1',11,'Quelle est la différence entre une blockchain publique et une blockchain permissionnée ?','["Aucune","Sur une publique, n''importe qui peut participer ; sur une permissionnée, l''accès est contrôlé","La publique est gratuite, l''autre payante","La permissionnée n''utilise pas de blocs"]'::jsonb,1,'Bitcoin et Ethereum sont ouvertes à tous. Une blockchain d''entreprise réserve la validation à des participants autorisés.');
insert into public.questions values('s1',12,'Quand a été miné le bloc genèse de Bitcoin ?','["Janvier 2009","Octobre 2008","Mars 2013","Juillet 2015"]'::jsonb,0,'Le livre blanc date d''octobre 2008, le bloc genèse du 3 janvier 2009.');
insert into public.questions values('s1',13,'Que signifie « immuable » pour une blockchain, en pratique ?','["Rien ne peut jamais changer, même en théorie","Modifier l''historique est si coûteux que c''est pratiquement impossible","Les prix ne bougent pas","Le code ne peut jamais être mis à jour"]'::jsonb,1,'L''immuabilité est économique et pratique, pas absolue : elle repose sur le coût d''une réécriture.');
insert into public.questions values('s1',14,'Qu''est-ce qu''un contrat intelligent ?','["Un contrat papier signé chez un notaire","Un programme sur la blockchain qui s''exécute automatiquement selon ses règles","Une IA qui négocie","Un accord entre mineurs"]'::jsonb,1,'C''est du code déployé sur la chaîne : si les conditions sont remplies, il s''exécute sans intermédiaire.');
insert into public.questions values('s1',15,'Quel est le rôle d''un oracle ?','["Prédire le prix futur","Apporter à la blockchain des données du monde extérieur","Miner des blocs","Garder les clés"]'::jsonb,1,'Une blockchain ne voit pas le monde extérieur. L''oracle lui transmet des données comme un cours ou un résultat sportif.');
insert into public.questions values('s1',16,'Qu''est-ce qui caractérise un NFT ?','["Il est interchangeable avec un autre","Il est unique et non interchangeable","C''est toujours une image","Il n''a pas de propriétaire"]'::jsonb,1,'Non fongible veut dire qu''un jeton n''équivaut pas à un autre, contrairement à un bitcoin qui vaut un autre bitcoin.');
insert into public.questions values('s1',17,'Qu''est-ce qu''un stablecoin ?','["Une crypto dont la valeur suit un actif de référence comme le dollar","Une crypto qui ne peut pas baisser","Une crypto minée lentement","Une monnaie de banque centrale"]'::jsonb,0,'USDT ou USDC suivent le dollar. Leur stabilité dépend des réserves ou du mécanisme qui les soutient.');
insert into public.questions values('s1',18,'Quels sont les trois termes du « trilemme de la blockchain » ?','["Prix, volume, liquidité","Décentralisation, sécurité, scalabilité","Vitesse, frais, design","Minage, staking, trading"]'::jsonb,1,'Il est difficile d''obtenir les trois à la fois : gagner en débit se paie souvent en décentralisation.');
insert into public.questions values('s1',19,'À quoi sert une solution de couche 2 (layer 2) ?','["Remplacer la blockchain principale","Traiter des transactions hors de la chaîne principale puis régler le résultat dessus","Doubler l''offre de jetons","Stocker des fichiers"]'::jsonb,1,'Lightning pour Bitcoin ou les rollups pour Ethereum augmentent le débit en s''appuyant sur la sécurité de la couche 1.');
insert into public.levels(id,ord,title,src) values('s2',2,'Bitcoin et monnaie numérique','Q&R n°2 · Garrick Hileman') on conflict(id) do update set ord=excluded.ord,title=excluded.title,src=excluded.src;
insert into public.questions values('s2',0,'Quel est le nombre maximal de bitcoins ?','["21 millions","100 millions","Illimité","2,1 milliards"]'::jsonb,0,'L''offre est plafonnée à 21 millions par le protocole.');
insert into public.questions values('s2',1,'Que divise un halving ?','["Le prix du bitcoin","La récompense de bloc des mineurs","Les frais de transaction","Le nombre de nœuds"]'::jsonb,1,'Tous les 210 000 blocs, soit environ quatre ans, la nouvelle émission par bloc est divisée par deux.');
insert into public.questions values('s2',2,'Après le halving d''avril 2024, quelle est la subvention par bloc ?','["6,25 BTC","3,125 BTC","12,5 BTC","1,5625 BTC"]'::jsonb,1,'Elle est passée de 6,25 à 3,125 BTC. Le prochain halving est attendu vers 2028.');
insert into public.questions values('s2',3,'Quel est le temps moyen entre deux blocs Bitcoin ?','["1 minute","10 minutes","1 heure","15 secondes"]'::jsonb,1,'Environ 10 minutes, maintenu par l''ajustement de difficulté.');
insert into public.questions values('s2',4,'Tous les combien la difficulté de minage s''ajuste-t-elle ?','["Chaque bloc","Tous les 2016 blocs, environ deux semaines","Chaque année","Jamais"]'::jsonb,1,'Si les blocs ont été trop rapides, la difficulté monte ; trop lents, elle baisse.');
insert into public.questions values('s2',5,'Comment s''appelle la plus petite unité de bitcoin ?','["Le wei","Le satoshi","Le lovelace","Le gwei"]'::jsonb,1,'1 satoshi = 0,00000001 BTC.');
insert into public.questions values('s2',6,'Selon quoi se calculent les frais d''une transaction Bitcoin ?','["Le montant envoyé","La taille de la transaction en données et la demande du moment","La distance entre les pays","L''âge du portefeuille"]'::jsonb,1,'On paie la place occupée dans le bloc (en vbytes), pas la somme envoyée.');
insert into public.questions values('s2',7,'Qu''est-ce que le mempool ?','["La réserve d''un exchange","La file d''attente des transactions pas encore incluses dans un bloc","Un pool de minage","Un portefeuille froid"]'::jsonb,1,'Les mineurs y piochent en priorité les transactions qui paient le plus par octet.');
insert into public.questions values('s2',8,'Combien de confirmations considère-t-on traditionnellement comme très sûr ?','["1","3","6","100"]'::jsonb,2,'Six blocs empilés au-dessus rendent une annulation extrêmement improbable.');
insert into public.questions values('s2',9,'Que s''est-il passé le 22 mai 2010 ?','["Le premier halving","L''achat de deux pizzas pour 10 000 BTC","La création d''Ethereum","Le premier ETF"]'::jsonb,1,'C''est le Bitcoin Pizza Day, premier achat connu d''un bien réel en bitcoin.');
insert into public.questions values('s2',10,'Sur quoi repose la valeur d''une monnaie fiduciaire comme l''euro ?','["Sur l''or stocké en banque","Sur la confiance et le cours légal fixé par l''État","Sur la puissance de calcul","Sur le pétrole"]'::jsonb,1,'Depuis la fin de l''étalon-or, sa valeur tient à la confiance dans l''émetteur et à son statut légal.');
insert into public.questions values('s2',11,'Quelles sont les trois fonctions classiques de la monnaie ?','["Épargne, crédit, impôt","Moyen d''échange, unité de compte, réserve de valeur","Création, destruction, transfert","Achat, vente, location"]'::jsonb,1,'Le débat sur Bitcoin porte surtout sur son rôle de réserve de valeur.');
insert into public.questions values('s2',12,'Sur quel argument repose l''idée de Bitcoin « or numérique » ?','["Il est jaune","Sa rareté est programmée et vérifiable","Il est garanti par les banques","Il est stable"]'::jsonb,1,'Comme l''or, il est rare et coûteux à produire, mais son offre est connue à l''avance.');
insert into public.questions values('s2',13,'Qu''est-ce qu''une CBDC ?','["Une crypto décentralisée","Une monnaie numérique émise par une banque centrale","Un stablecoin privé","Un ETF"]'::jsonb,1,'L''euro numérique en est un exemple : numérique, mais centralisé et contrôlé par l''émetteur.');
insert into public.questions values('s2',14,'Quel pays a fait du bitcoin une monnaie légale en 2021 ?','["La Suisse","Le Salvador","Le Japon","Le Canada"]'::jsonb,1,'Le Salvador, en septembre 2021. Le statut a ensuite été assoupli en 2025 dans le cadre d''un accord avec le FMI.');
insert into public.questions values('s2',15,'Quand les ETF bitcoin au comptant ont-ils été autorisés aux États-Unis ?','["Janvier 2024","Décembre 2017","Mars 2021","Ils ne l''ont jamais été"]'::jsonb,0,'La SEC les a approuvés le 10 janvier 2024, ouvrant l''accès aux investisseurs institutionnels.');
insert into public.questions values('s2',16,'Qu''apporte le Lightning Network ?','["Plus de bitcoins","Des paiements rapides et peu chers via des canaux hors chaîne","Un nouveau consensus","L''anonymat complet"]'::jsonb,1,'Deux parties ouvrent un canal sur la chaîne, échangent autant qu''elles veulent hors chaîne, puis règlent le solde.');
insert into public.questions values('s2',17,'Bitcoin est-il anonyme ?','["Oui, totalement","Non, il est pseudonyme : toutes les transactions sont publiques et traçables","Seulement le week-end","Uniquement avec un exchange"]'::jsonb,1,'Les adresses ne portent pas de nom, mais l''analyse de chaîne peut relier une adresse à une identité.');
insert into public.questions values('s2',18,'Quelle est la différence entre un soft fork et un hard fork ?','["Le soft fork reste compatible avec les anciens nœuds, le hard fork non","Le hard fork est plus rapide","Le soft fork crée une nouvelle crypto","Aucune"]'::jsonb,0,'SegWit et Taproot étaient des soft forks. Bitcoin Cash est né d''un hard fork en 2017.');
insert into public.questions values('s2',19,'De quoi se compose la rémunération d''un mineur ?','["Uniquement des frais","De la subvention de bloc et des frais des transactions incluses","D''un salaire de la fondation","Des intérêts bancaires"]'::jsonb,1,'À mesure que la subvention diminue, les frais devront prendre le relais pour financer la sécurité.');
insert into public.levels(id,ord,title,src) values('s3',3,'Blockchains programmables : Cardano et Ethereum','Q&R n°3 · John Greene, Cardano Foundation') on conflict(id) do update set ord=excluded.ord,title=excluded.title,src=excluded.src;
insert into public.questions values('s3',0,'Qui a principalement conçu Ethereum, lancé en 2015 ?','["Satoshi Nakamoto","Vitalik Buterin","Charles Hoskinson seul","Changpeng Zhao"]'::jsonb,1,'Vitalik Buterin l''a décrit en 2013, avec plusieurs cofondateurs dont Charles Hoskinson.');
insert into public.questions values('s3',1,'Qu''exécute l''EVM ?','["Le minage de bitcoins","Les contrats intelligents d''Ethereum","Les paiements Lightning","Les mises à jour de portefeuille"]'::jsonb,1,'L''Ethereum Virtual Machine exécute le code des contrats de façon identique sur tous les nœuds.');
insert into public.questions values('s3',2,'À quoi correspond le gas sur Ethereum ?','["Au prix de l''ETH","À la quantité de calcul nécessaire, payée en frais","À la vitesse du réseau","Au nombre de validateurs"]'::jsonb,1,'Chaque opération coûte du gas : plus un contrat calcule, plus la transaction coûte.');
insert into public.questions values('s3',3,'Qui a fondé Cardano ?','["Vitalik Buterin","Charles Hoskinson, cofondateur d''Ethereum","Gavin Wood","Satoshi Nakamoto"]'::jsonb,1,'Charles Hoskinson a quitté Ethereum et lancé Cardano, via IOHK (aujourd''hui Input Output).');
insert into public.questions values('s3',4,'Quel protocole de consensus utilise Cardano ?','["Proof of Work","Ouroboros, une preuve d''enjeu","Proof of Authority","Tendermint"]'::jsonb,1,'Ouroboros est une famille de protocoles de preuve d''enjeu publiés avec preuves de sécurité.');
insert into public.questions values('s3',5,'Quel modèle comptable utilise Cardano ?','["Le modèle à comptes","L''eUTXO, des UTXO étendus","Un registre bancaire","Le modèle DAG"]'::jsonb,1,'Cardano étend le modèle de Bitcoin pour y attacher du code et des données.');
insert into public.questions values('s3',6,'Quel avantage pratique offre le modèle eUTXO ?','["Des frais nuls","Des frais et un résultat connus avant d''envoyer la transaction","Des blocs plus gros","Pas besoin de portefeuille"]'::jsonb,1,'Une transaction peut être validée localement : elle réussit ou échoue sans payer de frais pour un échec imprévu.');
insert into public.questions values('s3',7,'Sur quel langage repose Plutus, le langage des contrats de Cardano ?','["Solidity","Haskell","Python","Rust"]'::jsonb,1,'Haskell est un langage fonctionnel qui se prête à la vérification formelle.');
insert into public.questions values('s3',8,'Qu''est-ce qui distingue la démarche de développement de Cardano ?','["Le développement le plus rapide possible","L''appui sur la recherche académique évaluée par des pairs","L''absence de documentation","Un code fermé"]'::jsonb,1,'Les protocoles sont publiés et relus avant d''être implémentés, au prix d''un rythme plus lent.');
insert into public.questions values('s3',9,'Que se passe-t-il quand on délègue ses ADA à un pool ?','["Les ADA quittent votre portefeuille pendant un an","Les ADA restent dans votre portefeuille et restent disponibles","Les ADA sont brûlés","Le pool devient propriétaire"]'::jsonb,1,'Le staking sur Cardano est liquide : pas de verrouillage, vous gardez la garde de vos jetons.');
insert into public.questions values('s3',10,'Quand Ethereum est-il passé à la preuve d''enjeu ?','["The Merge, septembre 2022","Juillet 2015","Janvier 2020","Il est toujours en preuve de travail"]'::jsonb,0,'The Merge a réduit la consommation électrique du réseau de plus de 99 %.');
insert into public.questions values('s3',11,'Quel est le rôle de la Cardano Foundation ?','["Miner les blocs","Une entité suisse indépendante qui promeut l''adoption et soutient la gouvernance de Cardano","Fixer le prix de l''ADA","Émettre des ADA"]'::jsonb,1,'Basée à Zoug, elle travaille sur l''adoption par les entreprises, l''éducation et la gouvernance.');
insert into public.questions values('s3',12,'Comment s''appelle l''ère de gouvernance décentralisée de Cardano ?','["Byron","Shelley","Voltaire","Goguen"]'::jsonb,2,'Voltaire, avec la CIP-1694, a introduit le vote on-chain et les représentants délégués (DReps).');
insert into public.questions values('s3',13,'Quelle particularité ont les jetons natifs sur Cardano ?','["Ils nécessitent un contrat intelligent comme les ERC-20","Ils sont gérés directement par le registre, sans contrat intelligent","Ils sont interdits","Ils ne peuvent pas être échangés"]'::jsonb,1,'Sur Ethereum, un jeton ERC-20 est un contrat. Sur Cardano, le registre gère les jetons nativement, comme l''ADA.');
insert into public.questions values('s3',14,'Que désigne la DeFi ?','["Les services financiers des banques en ligne","Des services financiers (prêt, échange, épargne) fonctionnant par contrats intelligents sans intermédiaire","La défiscalisation","Un indice boursier"]'::jsonb,1,'Uniswap, Aave ou sur Cardano Minswap et Liqwid en sont des exemples.');
insert into public.questions values('s3',15,'Qu''est-ce qu''une DAO ?','["Une banque décentralisée","Une organisation dont les règles et les votes sont gérés par contrats intelligents","Un type de NFT","Un exchange centralisé"]'::jsonb,1,'Les détenteurs de jetons de gouvernance votent les décisions, appliquées par le code.');
insert into public.questions values('s3',16,'Quel est le principal risque d''un contrat intelligent ?','["Il est trop lent","Une faille dans le code peut être exploitée et les fonds volés","Il coûte trop cher à lire","Il disparaît après un an"]'::jsonb,1,'Le piratage de The DAO en 2016 a conduit au hard fork d''Ethereum et à la naissance d''Ethereum Classic.');
insert into public.questions values('s3',17,'Que signifie la composabilité en DeFi ?','["Les protocoles peuvent s''assembler comme des briques","Les jetons peuvent être fusionnés","Les blocs sont compressés","Le code peut être réécrit"]'::jsonb,0,'On parle de « legos monétaires » : un protocole en utilise un autre directement.');
insert into public.questions values('s3',18,'Pourquoi les ponts entre blockchains (bridges) sont-ils souvent visés par les pirates ?','["Ils sont lents","Ils concentrent de gros montants verrouillés et une logique complexe","Ils n''ont pas de code","Ils sont gérés par l''État"]'::jsonb,1,'Ronin (environ 600 M$) et Wormhole (environ 320 M$) comptent parmi les plus gros vols de l''histoire.');
insert into public.questions values('s3',19,'Comment s''appelle la plus petite unité de l''ADA ?','["Le satoshi","Le lovelace","Le wei","Le gwei"]'::jsonb,1,'1 ADA = 1 000 000 lovelace, en hommage à Ada Lovelace.');
insert into public.levels(id,ord,title,src) values('s4',4,'Sécurité et confidentialité des portefeuilles','Q&R n°4 · Lucien, Trezor') on conflict(id) do update set ord=excluded.ord,title=excluded.title,src=excluded.src;
insert into public.questions values('s4',0,'Que signifie « not your keys, not your coins » ?','["Les clés USB sont dangereuses","Si vous ne détenez pas les clés privées, vous ne contrôlez pas vraiment vos cryptos","Il faut changer de clé chaque mois","Les exchanges sont toujours sûrs"]'::jsonb,1,'Sur une plateforme, vous détenez une créance. FTX, Celsius ou AscendEX ont montré ce que cela peut coûter.');
insert into public.questions values('s4',1,'Qu''est-ce que la garde personnelle (self-custody) ?','["Confier ses cryptos à un exchange","Détenir soi-même ses clés privées","Assurer ses cryptos","Les stocker chez un notaire"]'::jsonb,1,'Vous êtes seul responsable, sans intermédiaire qui puisse bloquer ou perdre vos fonds.');
insert into public.questions values('s4',2,'Que représente la phrase de récupération de 12 ou 24 mots ?','["Un mot de passe de connexion à l''appli","Le portefeuille lui-même : quiconque la possède contrôle les fonds","Un code de support","Une adresse de réception"]'::jsonb,1,'Toutes les clés privées en dérivent. Perdre l''appareil n''est rien si on a la phrase ; perdre la phrase, si.');
insert into public.questions values('s4',3,'Où conserver sa phrase de récupération ?','["En photo sur son téléphone","Dans un e-mail à soi-même","Sur un support physique hors ligne, papier ou métal","Dans un gestionnaire de notes cloud"]'::jsonb,2,'Jamais sur un appareil connecté. Le métal résiste au feu et à l''eau.');
insert into public.questions values('s4',4,'Un « support technique » vous demande votre phrase de récupération. Que faire ?','["La donner pour débloquer le compte","Refuser : aucun service légitime ne la demande jamais","N''en donner que les 12 premiers mots","La dicter par téléphone"]'::jsonb,1,'C''est l''arnaque la plus répandue. Même une partie de la phrase réduit fortement la sécurité.');
insert into public.questions values('s4',5,'À quoi sert une passphrase (le « 25e mot ») ?','["À accélérer les transactions","À ouvrir un portefeuille caché : la phrase seule ne suffit plus à vider les fonds","À remplacer le code PIN","À réduire les frais"]'::jsonb,1,'Chaque passphrase dérive un portefeuille différent. Un voleur qui trouve les 24 mots ne voit que le portefeuille sans passphrase.');
insert into public.questions values('s4',6,'Que se passe-t-il si vous oubliez votre passphrase ?','["Trezor peut la réinitialiser","Les fonds de ce portefeuille sont définitivement perdus","On la retrouve dans l''appli","Rien, la phrase de 24 mots suffit"]'::jsonb,1,'La passphrase n''est stockée nulle part. Elle se sauvegarde séparément de la phrase, sur un autre support.');
insert into public.questions values('s4',7,'Comment fonctionne une sauvegarde Shamir (SLIP-39) ?','["La phrase est copiée trois fois","Le secret est découpé en parts ; il en faut un nombre minimal (par exemple 2 sur 3) pour le reconstituer","On utilise trois portefeuilles différents","Les mots sont chiffrés par Trezor"]'::jsonb,1,'Une part seule ne révèle rien, et perdre une part n''est pas grave si le seuil reste atteignable.');
insert into public.questions values('s4',8,'Quelle est la différence entre Shamir et multisig ?','["Aucune","Shamir découpe la sauvegarde d''une seule clé ; le multisig exige plusieurs clés distinctes qui signent chacune","Le multisig est réservé à Ethereum","Shamir est plus ancien"]'::jsonb,1,'Avec Shamir, la clé est reconstituée à un moment. Avec le multisig, elle n''existe jamais en un seul endroit.');
insert into public.questions values('s4',9,'Quel est l''intérêt d''un multisig 2 sur 3 ?','["Doubler ses bitcoins","Perdre ou se faire voler une clé sans perdre les fonds","Envoyer sur trois blockchains","Payer moins de frais"]'::jsonb,1,'Il supprime le point de défaillance unique : un attaquant doit compromettre deux clés.');
insert into public.questions values('s4',10,'Votre nouveau portefeuille arrive avec une phrase déjà imprimée dans la boîte. Que conclure ?','["C''est pratique","C''est normal sur les nouveaux modèles","C''est une attaque de la chaîne d''approvisionnement : ne pas l''utiliser","Il suffit de changer le PIN"]'::jsonb,2,'La phrase doit toujours être générée par l''appareil, devant vous. Une phrase fournie est connue de quelqu''un d''autre.');
insert into public.questions values('s4',11,'Où acheter un portefeuille matériel ?','["Sur une place de marché d''occasion, c''est moins cher","Directement chez le fabricant ou un revendeur officiel","Auprès d''un vendeur sur Telegram","Peu importe"]'::jsonb,1,'Un appareil d''occasion ou de source douteuse peut avoir été modifié.');
insert into public.questions values('s4',12,'Pourquoi vérifier l''adresse de réception sur l''écran du portefeuille matériel ?','["Pour le design","Parce qu''un logiciel malveillant peut remplacer l''adresse affichée ou copiée sur l''ordinateur","Pour économiser des frais","Ce n''est pas utile"]'::jsonb,1,'L''écran de l''appareil est la seule source de confiance. Certains malwares remplacent l''adresse dans le presse-papiers.');
insert into public.questions values('s4',13,'Qu''est-ce que l''empoisonnement d''adresse (address poisoning) ?','["Un virus dans la blockchain","L''envoi d''une petite transaction depuis une adresse qui ressemble à la vôtre pour qu''on la recopie par erreur","Un bug de Trezor","Une attaque à 51 %"]'::jsonb,1,'L''attaquant mise sur la copie depuis l''historique. Vérifiez toujours l''adresse entière, pas seulement le début et la fin.');
insert into public.questions values('s4',14,'Que fait un « drainer » quand vous signez une approbation illimitée ?','["Il accélère vos transactions","Il peut ensuite retirer vos jetons sans nouvelle autorisation","Il bloque votre compte","Il vous rembourse"]'::jsonb,1,'Lisez ce que vous signez et révoquez régulièrement les approbations inutiles.');
insert into public.questions values('s4',15,'Pourquoi un portefeuille matériel protège-t-il mieux qu''une appli ?','["Il est plus cher","Les clés privées ne quittent jamais l''appareil : il signe en interne","Il est plus rapide","Il n''a pas besoin de phrase"]'::jsonb,1,'Même sur un ordinateur infecté, l''attaquant ne peut pas extraire la clé, seulement tenter de vous faire signer.');
insert into public.questions values('s4',16,'Quelle est la différence entre portefeuille chaud et froid ?','["La couleur de l''appareil","Le chaud est connecté à Internet, le froid garde les clés hors ligne","Le froid est pour l''épargne en euros","Il n''y en a pas"]'::jsonb,1,'On garde peu de fonds sur un portefeuille chaud, pour l''usage courant, et l''épargne au froid.');
insert into public.questions values('s4',17,'Pourquoi faire tourner son propre nœud complet ?','["Pour miner plus","Pour vérifier soi-même les transactions et ne pas révéler ses adresses à un serveur tiers","Pour payer moins d''impôts","C''est obligatoire"]'::jsonb,1,'Sans nœud, votre portefeuille interroge le serveur de quelqu''un d''autre, qui voit vos adresses et votre solde.');
insert into public.questions values('s4',18,'Qu''est-ce qui caractérise un Coldcard ?','["Il est multi-cryptos","Il est dédié à Bitcoin et peut fonctionner sans connexion directe (air-gapped), via carte microSD","Il se connecte en Wi-Fi","Il n''a pas d''écran"]'::jsonb,1,'Les transactions partiellement signées (PSBT) transitent par carte mémoire, sans câble vers l''ordinateur.');
insert into public.questions values('s4',19,'Quelle règle de base limite la casse en cas d''erreur ?','["Tout garder sur un seul exchange","Tester d''abord une petite transaction avant un gros envoi","Partager sa phrase avec un proche par SMS","Ne jamais mettre à jour son appareil"]'::jsonb,1,'Un petit envoi de test confirme l''adresse et le réseau avant de déplacer une somme importante.');
insert into public.levels(id,ord,title,src) values('s5',5,'Finance décentralisée (DeFi)','Session 5 · support PDF, tutoriels et Q&R n°5 · Luke Martinez, Avalanche Team1') on conflict(id) do update set ord=excluded.ord,title=excluded.title,src=excluded.src;
insert into public.questions values('s5',0,'Quels sont les deux piliers de la finance traditionnelle que la DeFi cherche à supprimer ?','["La garde des actifs par un tiers et l''accès sur autorisation lié à l''identité","Les taux d''intérêt et l''inflation","Les impôts et la régulation","Les billets et les pièces"]'::jsonb,0,'En TradFi, une institution garde vos actifs (vous détenez une créance) et filtre qui peut participer. La DeFi vise la garde personnelle et l''accès sans permission.');
insert into public.questions values('s5',1,'Le site web d''Uniswap et ses contrats intelligents appartiennent à quelles couches de la pile DeFi ?','["Les deux à la couche de règlement","Le site à la couche application, les contrats à la couche protocole","Le site à la couche protocole, les contrats à la couche actifs","Les deux à la couche d''agrégation"]'::jsonb,1,'Le site n''est qu''une porte d''entrée. L''application, ce sont les contrats : ils restent utilisables même si le site tombe.');
insert into public.questions values('s5',2,'Pourquoi les prêts DeFi sont-ils surcollatéralisés ?','["Pour enrichir les développeurs","Parce que sans identité, score de crédit ni tribunal, seul le collatéral garantit le remboursement","Parce que la loi l''impose","Pour payer moins de gas"]'::jsonb,1,'Un emprunteur pseudonyme n''aurait aucune raison de rembourser si sa garantie valait moins que sa dette. Le collatéral est le mécanisme d''exécution.');
insert into public.questions values('s5',3,'Tu déposes 5 ETH à 3 000 $ et empruntes 10 000 USDC. Le seuil de liquidation est de 120 %. À quel prix de l''ETH la liquidation commence-t-elle ?','["2 000 $","2 250 $","2 400 $","2 700 $"]'::jsonb,2,'120 % de 10 000 $ = 12 000 $ de garantie, soit 12 000 ÷ 5 = 2 400 $ par ETH. Une baisse de 20 % suffit.');
insert into public.questions values('s5',4,'Mango Markets, octobre 2022 : environ 114 M$ retirés. Qu''est-ce qui a été manipulé ?','["L''oracle a été piraté et a menti","Le marché d''un jeton peu échangé (MNGO) : l''oracle a fidèlement rapporté un prix gonflé","La clé privée d''un administrateur","Le consensus de Solana"]'::jsonb,1,'L''oracle a dit vrai sur un marché faussé. Un protocole n''est fiable que si les prix qu''il reçoit le sont, d''où le danger des jetons peu liquides.');
insert into public.questions values('s5',5,'Qu''est-ce qui distingue un prêt flash ?','["Il dure 24 heures","Il est emprunté et remboursé dans la même transaction, sinon tout est annulé","Il exige un collatéral de 150 %","Il est réservé aux banques"]'::jsonb,1,'Sans collatéral ni identité, mais sans risque de défaut : si le remboursement (plus 0,05 % sur Aave V3) n''arrive pas avant la fin de la transaction, rien ne s''exécute.');
insert into public.questions values('s5',6,'Comment l''attaquant de Beanstalk (avril 2022) a-t-il vidé 182 M$ ?','["Il a volé une clé privée","Un prêt flash d''un milliard lui a donné environ 79 % des votes pour faire passer sa propre proposition","Il a manipulé un oracle Chainlink","Il a fait une attaque à 51 % sur Ethereum"]'::jsonb,1,'C''est une attaque de gouvernance. Défenses : délai entre vote et exécution, et droits de vote mesurés sur des soldes passés.');
insert into public.questions values('s5',7,'Pourquoi un carnet d''ordres classique fonctionne-t-il mal sur une blockchain comme Ethereum ?','["Les ordres sont secrets","Chaque ordre ou annulation coûte du gas, les teneurs de marché fuient et les ordres visibles se font devancer","Les blockchains ne connaissent pas les prix","C''est interdit par la loi"]'::jsonb,1,'Coût, liquidité faible et délai des blocs. D''où les pools et les AMM. Exception : des chaînes à très haut débit comme Hyperliquid.');
insert into public.questions values('s5',8,'Un pool contient 100 ETH et 300 000 USDC (x · y = k). Alice vend 10 ETH. Quel prix affiche le pool ensuite ?','["3 000 $","2 727 $","2 479 $","2 700 $"]'::jsonb,2,'k = 30 000 000. Avec 110 ETH, il reste 272 727 USDC : le prix devient 272 727 ÷ 110 ≈ 2 479 $. Alice a obtenu en moyenne 2 727 $ par ETH.');
insert into public.questions values('s5',9,'Même échange de 10 ETH, mais dans un pool deux fois plus profond. Que se passe-t-il ?','["Le glissement double","Le glissement est à peu près divisé par deux","Le prix ne bouge pas du tout","L''échange est refusé"]'::jsonb,1,'Plus le pool est profond, moins un échange déplace le prix : environ 2 857 $ par ETH au lieu de 2 727 $.');
insert into public.questions values('s5',10,'Qu''est-ce que la perte impermanente d''un fournisseur de liquidité ?','["Les frais de gas payés au dépôt","Le manque à gagner par rapport à la simple détention des jetons, causé par l''arbitrage quand le prix bouge","Un piratage du pool","L''impôt sur les plus-values"]'::jsonb,1,'L''arbitragiste rachète au pool le jeton qui monte : le LP vend ses gagnants et achète ses perdants. Elle ne devient réelle qu''au retrait.');
insert into public.questions values('s5',11,'Pour un pool 50/50, le prix d''un jeton double ou est divisé par deux. Quelle perte impermanente dans chaque cas ?','["Gain si ça double, perte si ça baisse","Environ −5,7 % dans les deux cas","−50 % dans les deux cas","Aucune perte"]'::jsonb,1,'Formule 2√r ÷ (1 + r) − 1 : c''est le multiple qui compte, pas le sens. ×2 ou ×½ donne −5,7 % ; ×5 ou ×⅕ donne −25,5 %.');
insert into public.questions values('s5',12,'Pourquoi les pools de stablecoins comme USDC/USDT (Curve) subissent-ils très peu de perte impermanente ?','["Ils ne paient pas de frais","Le rapport de prix entre les deux jetons reste proche de 1","Ils sont assurés par l''État","Ils ne sont pas sur une blockchain"]'::jsonb,1,'Sans écart de prix, l''arbitrage n''a rien à prendre au LP. La perte grandit avec l''ampleur du mouvement.');
insert into public.questions values('s5',13,'Sur Uniswap v3, que se passe-t-il quand le prix sort de la plage choisie par le LP ?','["Il gagne plus de frais","Sa position ne touche plus de frais et ne contient presque plus qu''un seul jeton","Ses fonds sont liquidés","La plage s''élargit automatiquement"]'::jsonb,1,'La liquidité concentrée rapporte plus par dollar tant qu''on est dans la plage, mais hors plage elle ne sert plus et on détient surtout le jeton le plus faible.');
insert into public.questions values('s5',14,'Tu fournis de la liquidité à une paire de deux grands stablecoins en dollar. Quel palier de frais choisir, d''après le tutoriel ?','["1 %, le plus élevé","Un palier très bas (0,01 % ou 0,05 %), car les traders attendent des frais minimes sur une paire stable","Peu importe","0,3 % obligatoirement"]'::jsonb,1,'Paire stable et très liquide : frais très bas. Paire de petits jetons exotiques : les traders acceptent jusqu''à 1 %. 0,3 % convient à la plupart des paires.');
insert into public.questions values('s5',15,'Sur Aave, que signifie un facteur de santé (health factor) qui passe sous 1 ?','["Le prêt est remboursé","La position peut être liquidée : un robot vend le collatéral pour rembourser la dette","Le taux d''intérêt baisse","Le collatéral est doublé"]'::jsonb,1,'L''emprunteur garde ce qu''il a emprunté mais perd sa garantie, avec une pénalité. Dans le tutoriel, il vise 2,73 pour garder une marge.');
insert into public.questions values('s5',16,'Tu déposes des USDC sur Aave. Que représente l''aToken que tu reçois ?','["Un jeton de gouvernance gratuit","Le reçu de ton dépôt, qui permet de récupérer tes fonds plus les intérêts","Une dette envers Aave","Un NFT de collection"]'::jsonb,1,'Garde-le précieusement : c''est lui qui prouve ton dépôt. Sur Uniswap v3, c''est un NFT qui joue ce rôle pour une position de liquidité.');
insert into public.questions values('s5',17,'Mars 2023 : la Silicon Valley Bank fait faillite et le DAI, stablecoin décentralisé, tombe vers 0,88 $. Pourquoi ?','["Le code du DAI avait un bug","Environ 36 % de sa garantie était de l''USDC, dont des réserves dormaient chez SVB","Ethereum était en panne","Les mineurs ont refusé ses transactions"]'::jsonb,1,'C''est la composabilité vue côté dominos : une position DeFi n''est jamais plus sûre que tout ce qui se trouve en dessous.');
insert into public.questions values('s5',18,'Tu stakes de l''AVAX via BENQI et reçois du sAVAX. Comment récupérer tes AVAX ?','["Instantanément et sans frais, toujours","Par le protocole (15 jours d''attente puis 2 jours pour réclamer) ou en vendant le sAVAX sur le marché, au prix des acheteurs","Impossible, c''est bloqué à vie","Seulement en appelant le support"]'::jsonb,1,'Un jeton de staking liquide ne garantit pas une sortie instantanée : la voie rapide dépend des acheteurs et de la liquidité disponibles.');
insert into public.questions values('s5',19,'Selon Chainalysis, comment les piratages ont-ils évolué entre 2022 et 2025 ?','["Ils ont disparu","Ils sont passés des failles de code DeFi aux clés privées et aux personnes (Bybit, 1,5 Md$ en 2025)","Ils ne visent plus que Bitcoin","Ils ne touchent que les petits protocoles"]'::jsonb,1,'Le code DeFi s''est durci : les attaquants piègent désormais les signataires, comme chez Bybit ou Drift en 2026.');
insert into public.levels(id,ord,title,src) values('s6',6,'Les marchés prédictifs','Session 6 · support PDF, vidéo Polymarket et Q&R n°6 · Apostolos Kourtis') on conflict(id) do update set ord=excluded.ord,title=excluded.title,src=excluded.src;
insert into public.questions values('s6',0,'Sur un marché prédictif, un contrat OUI s''échange à 0,72 $. Comment le lit-on ?','["72 % de chances que l''événement se produise, selon le marché","Un gain garanti de 72 %","72 % des traders ont voté OUI","Le contrat paiera 0,72 $ si OUI gagne"]'::jsonb,0,'Un OUI paie 1 $ si la condition est remplie, 0 $ sinon. Son prix entre 0 et 1 $ se lit comme une probabilité implicite du marché, ici environ 72 %. C''est une approximation, pas une vérité.');
insert into public.questions values('s6',1,'Tu achètes un OUI à 0,30 $ puis tu le revends à 0,45 $ avant la fin. Quel est ton résultat ?','["Tu perds, car l''événement ne s''est pas encore produit","+0,15 $ par contrat avant frais, quel que soit le résultat final","+0,70 $ par contrat","Tu dois attendre le règlement pour savoir"]'::jsonb,1,'On n''est pas obligé d''attendre le règlement : on peut revendre à tout moment. 0,45 − 0,30 = 0,15 $ de gain, comme sur n''importe quel marché.');
insert into public.questions values('s6',2,'En 1906, 800 visiteurs d''une foire anglaise estiment le poids d''un bœuf. Qu''observe Francis Galton ?','["La foule se trompe lourdement, comme il le pensait","La médiane des estimations tombe à moins de 1 % du poids réel, mieux que chaque expert","Seuls les bouchers trouvent le bon poids","Les estimations sont réparties au hasard"]'::jsonb,1,'C''est la sagesse des foules : chacun détient un morceau d''information et l''agrégation annule les erreurs individuelles. Un marché prédictif fait la même chose, en temps réel et avec une incitation financière.');
insert into public.questions values('s6',3,'Pendant le Q&R, le professeur demande aux étudiants de prédire la décision de la Cour suprême. Pourquoi est-ce un sondage et pas un marché prédictif ?','["Parce qu''il y avait trop peu de participants","Parce qu''aucune récompense ne venait d''une bonne réponse : sans incitation à être précis, ce sont des opinions","Parce que la question était binaire","Parce que le vote était anonyme"]'::jsonb,1,'Ce qui fait un marché prédictif, c''est l''incitation : on met son argent là où est sa conviction. Sans gain ni perte, on obtient un sondage.');
insert into public.questions values('s6',4,'Une paire OUI + NON s''achète 0,97 $ au total. Que fait un arbitragiste ?','["Rien, c''est normal","Il achète la paire : elle paiera toujours 1 $, soit 0,03 $ de gain sans risque avant frais","Il vend uniquement le NON","Il attend que le prix monte à 1,10 $"]'::jsonb,1,'OUI + NON paie toujours exactement 1 $. Si la paire coûte moins, l''acheter verrouille un profit. C''est ce qui force les deux prix à rester cohérents.');
insert into public.questions values('s6',5,'Quelle différence entre un bookmaker et un marché prédictif ?','["Aucune, ce sont deux casinos","Le bookmaker fixe les cotes avec sa marge et gagne quand tu perds ; sur un marché, les prix naissent des échanges entre traders et la plateforme vit des frais","Le marché prédictif fixe des cotes fixes","Le bookmaker ne prend pas de marge"]'::jsonb,1,'Chez un bookmaker, l''espérance tourne souvent autour de −10 % et les gagnants réguliers sont limités ou bannis. Un marché prédictif est une bourse : on parie contre d''autres traders.');
insert into public.questions values('s6',6,'Un festival perd 40 000 $ s''il pleut. Il achète 10 000 OUI « pluie » à 25 ¢. Quel usage fait-il du marché ?','["De la spéculation pure","Une couverture partielle : 2 500 $ dépensés, 10 000 $ touchés s''il pleut","Une prévision pour la météo","Un délit d''initié"]'::jsonb,1,'C''est du hedging : on compense une perte liée à un événement précis. Ici la couverture n''est que partielle (10 000 $ sur 40 000 $).');
insert into public.questions values('s6',7,'Sur Polymarket, un marché affiche bid 17 ¢ et ask 18 ¢. Quelle probabilité est affichée et quel est l''écart (spread) ?','["17 % et 18 ¢","Environ 18 % (le milieu bid–ask) et 1 ¢","35 % et 1 ¢","83 % et 17 ¢"]'::jsonb,1,'Polymarket affiche le point médian entre la meilleure offre d''achat et de vente. Le spread = ask − bid = 1 ¢. C''est pourquoi acheter les deux côtés coûte 1,01 $.');
insert into public.questions values('s6',8,'Sur un marché, le volume bondit et l''intérêt ouvert grimpe fortement. Que faut-il soupçonner ?','["Rien, ce sont deux mesures identiques","De l''argent frais entre, parfois celui d''un seul gros trader : le mouvement de prix peut venir de l''argent plutôt que de l''information","Le marché va être annulé","Le spread est forcément nul"]'::jsonb,1,'Un pic de volume signale souvent une nouvelle information ; un intérêt ouvert qui monte signale de nouvelles positions. Lus ensemble, ils séparent un mouvement d''information d''un mouvement d''argent. Et un spread large signale un marché peu liquide.');
insert into public.questions values('s6',9,'Quand un teneur de marché automatisé (AMM) vaut-il mieux qu''un carnet d''ordres, et qui paie ?','["Toujours ; personne ne paie","Sur un marché peu liquide, car il cote toujours un prix ; les fournisseurs de liquidité ou le sponsor absorbent les pertes face aux traders informés","Sur un marché très liquide ; les traders paient","Jamais ; c''est interdit"]'::jsonb,1,'« Une rue pleine veut un carnet d''ordres, une rue vide a besoin d''un commerçant. » Le LMSR de Hanson est financé par la subvention d''un sponsor.');
insert into public.questions values('s6',10,'Lequel N''EST PAS un risque d''une plateforme de prédiction centralisée ?','["Le gel ou le retard des retraits","La plateforme décide seule du résultat","La blockchain ne connaît pas le monde réel","Les restrictions selon le pays"]'::jsonb,2,'Le problème de l''oracle concerne les marchés décentralisés. Les plateformes centralisées posent des risques de contrepartie, de retrait, de règlement opaque, de barrières géographiques et de cotation.');
insert into public.questions values('s6',11,'Dans le cycle de vie d''un marché décentralisé, quand l''oracle intervient-il ?','["À la création du marché","Pendant les échanges","À la résolution, après l''événement, suivi d''une période de contestation","Jamais, le contrat devine le résultat"]'::jsonb,2,'Création → négociation → résolution (rapport de l''oracle, période de contestation, escalade si litige) → règlement et paiement par le contrat intelligent.');
insert into public.questions values('s6',12,'Pourquoi les marchés décentralisés règlent-ils en stablecoins (USDC) ?','["C''est imposé par la CFTC","Pour que le prix d''un jeton de résultat ne reflète que la probabilité, pas la volatilité d''une crypto","Parce que l''ETH n''existe pas sur Polygon","Pour payer moins d''impôts"]'::jsonb,1,'Avec de l''ETH en collatéral, un pari gagnant pourrait être effacé par une chute de l''ETH. L''USDC isole l''information de la volatilité.');
insert into public.questions values('s6',13,'Sur Polymarket, un résultat proposé est contesté une première puis une seconde fois. Que se passe-t-il ?','["Le marché est annulé et remboursé","Polymarket tranche seul","La résolution passe au vote des détenteurs du jeton UMA, qui ont le dernier mot","Le premier proposant gagne d''office"]'::jsonb,2,'Oracle optimiste : proposition avec caution, fenêtre de contestation, deux contestations maximum, puis vote UMA. Un système in fine ploutocratique, comme dans l''affaire MicroStrategy de mai 2026.');
insert into public.questions values('s6',14,'Un oracle annonce le mauvais résultat et personne ne conteste. Que se passe-t-il ?','["Le contrat détecte l''erreur et annule","Le contrat paie les mauvais gagnants ; les vrais gagnants perdent, sans recours","La plateforme rembourse tout le monde","Le marché reste ouvert indéfiniment"]'::jsonb,1,'Le contrat exécute ce que dit l''oracle. C''est pourquoi la compromission de l''oracle est un point de défaillance unique.');
insert into public.questions values('s6',15,'Polymarket face à Kalshi : quelle affirmation est juste ?','["Kalshi règle en USDC sur blockchain","Polymarket : USDC, accès pseudonyme mondial, oracle avec contestation ; Kalshi : dollars, KYC, régulé par la CFTC, résolution par la plateforme","Les deux exigent un KYC","Polymarket est régulé par la CFTC depuis 2020"]'::jsonb,1,'Kalshi est la bourse centralisée réglementée ; Polymarket est l''infrastructure décentralisée. La création de marché coûte une caution d''environ 750 USDC chez Polymarket.');
insert into public.questions values('s6',16,'Comment fonctionne techniquement Polymarket ?','["Tout se passe on-chain, y compris le carnet d''ordres","Hybride : carnet d''ordres (CLOB) hors chaîne, fonds et règlement on-chain","Tout est centralisé comme une banque","Il n''y a pas de carnet d''ordres, seulement un AMM"]'::jsonb,1,'Hors chaîne pour la vitesse et la gratuité des ordres ; on-chain (Polygon) pour l''auto-conservation des fonds et un règlement vérifiable.');
insert into public.questions values('s6',17,'Sur Polymarket, quand tu cliques « acheter », que crée ton navigateur ?','["Une transaction Ethereum payée en gas","Un ordre signé avec ta clé privée (EIP-712) envoyé au carnet d''ordres, qui vérifie signature et fonds","Un e-mail au support","Un NFT"]'::jsonb,1,'L''ordre n''est pas une transaction blockchain : c''est une instruction signée (jeton, sens, prix, taille, expiration). Tous les ordres sont en réalité des ordres limités ; un « ordre au marché » est un limité exécutable tout de suite.');
insert into public.questions values('s6',18,'Fin octobre 2026, des comptes Polymarket ont été vidés. Comment ?','["Les contrats intelligents avaient un bug","L''oracle UMA a été corrompu","Un script tiers du site web, compromis via son DNS, a utilisé les autorisations déjà données par les utilisateurs connectés","Les clés privées ont été volées sur Polygon"]'::jsonb,2,'Ni la blockchain, ni l''oracle, ni les contrats n''ont été percés : le site web est un point faible centralisé. On peut d''ailleurs interagir directement avec le protocole sans passer par le site.');
insert into public.questions values('s6',19,'Affaire Maduro (janvier 2026) : qu''est-ce qui a fait soupçonner un délit d''initié sur Polymarket ?','["Des comptes créés juste avant, ne pariant que sur le Venezuela, avec un sans-faute","Le prix est resté à 50 %","Kalshi a annulé le marché","Les volumes étaient nuls"]'::jsonb,0,'Probabilité à ~9 % au début de l''opération, plus de 400 000 $ gagnés par un compte, 9 800 $ devenus 133 000 $ pour six portefeuilles. Le pseudonymat rend ce type d''abus difficile à poursuivre.');
insert into public.levels(id,ord,title,src) values('s7',7,'La géopolitique des cryptomonnaies','Session 7 · cours de Garrick Hileman et 7 articles de recherche') on conflict(id) do update set ord=excluded.ord,title=excluded.title,src=excluded.src;
insert into public.questions values('s7',0,'Selon Garrick Hileman, sous quelle forme une crypto aurait-elle le plus de poids géopolitique ?','["Comme « or numérique » détenu en réserve","Comme vraie monnaie : une unité de compte et un réseau de paiement intégrés, à la manière du dollar plus Visa","Comme jeton de gouvernance","Comme NFT de collection"]'::jsonb,1,'Un actif de réserve pèse peu. Une monnaie qui combine l''unité (le dollar) et le réseau (Visa, SWIFT) dans un même système toucherait au cœur du pouvoir monétaire des États.');
insert into public.questions values('s7',1,'Qui crée l''essentiel de la monnaie en circulation aujourd''hui ?','["Les banques centrales, en imprimant des billets","Les gouvernements, par l''impôt","Les banques commerciales, en accordant des prêts","Les mineurs de bitcoin"]'::jsonb,2,'Quand une banque accorde un crédit immobilier ou un prêt auto, elle crée de la monnaie. La part émise par les banques centrales est souvent inférieure à 10 % : la monnaie est déjà surtout privée, comme Bitcoin.');
insert into public.questions values('s7',2,'Dans la vue « emboîtée » des trois fonctions de la monnaie, laquelle est au cœur, donc la plus difficile à atteindre ?','["La réserve de valeur","Le moyen d''échange","L''unité de compte","La spéculation"]'::jsonb,2,'Réserve de valeur (cercle le plus large), puis moyen d''échange, puis unité de compte au centre. Bitcoin en est surtout à la première étape.');
insert into public.questions values('s7',3,'D''après Nick Szabo, pourquoi Bitcoin restera-t-il plus volatil qu''une monnaie de banque centrale ?','["Parce que ses exchanges manquent de liquidité","Parce que la spéculation reflète une incertitude réelle sur son avenir, que plus de liquidité ne réduit pas","Parce que son offre est illimitée","Parce que les mineurs vendent chaque jour"]'::jsonb,1,'La volatilité vient de l''incertitude sur le rôle futur de Bitcoin. De meilleurs mécanismes de liquidité ne suppriment pas cette incertitude-là.');
insert into public.questions values('s7',4,'Selon Hileman, quel est peut-être le plus grand obstacle pour qu''une crypto devienne un moyen d''échange ?','["Les frais de minage","Presque personne n''est payé en crypto : sans salaires, les commerçants ne l''acceptent pas, et inversement","Le manque d''exchanges","L''absence de portefeuilles mobiles"]'::jsonb,1,'C''est le problème de l''œuf et de la poule, toujours pas résolu 16 ans après Bitcoin. Les stablecoins pourraient aider à le débloquer.');
insert into public.questions values('s7',5,'Le 3 avril 2025, au lendemain des droits de douane massifs américains, quelle question Hileman juge-t-il clé ?','["Le prochain halving","L''indépendance de la Fed : prêtera-t-elle encore des dollars (lignes de swap) aux banques centrales étrangères en crise ?","La date des ETF ether","Le prix de l''or en euros"]'::jsonb,1,'En crise, la BCE ou la Banque du Japon appellent la Fed de New York pour emprunter des dollars. Si la Fed limitait cet accès pour renforcer la position de négociation de la Maison-Blanche, le dollar deviendrait une arme. Lecture conseillée : Secrets of the Temple, de William Greider.');
insert into public.questions values('s7',6,'Pourquoi la concentration de la détention de bitcoin est-elle un problème pour en faire une monnaie ?','["Elle fait baisser les frais","Une monnaie doit être largement répartie ; si l''État américain, Saylor ou BlackRock en détiennent de plus en plus, elle sert moins comme monnaie","Elle accélère les blocs","Elle n''a aucun effet"]'::jsonb,1,'Une monnaie utile circule entre beaucoup de mains. Satoshi seul détiendrait environ 5 % des BTC, autre facteur de concentration.');
insert into public.questions values('s7',7,'D''après Foley, Karlsen et Putniņš (« Sex, Drugs and Bitcoin »), quelle part des transactions bitcoin était liée à une activité illégale ?','["Environ 1 %","Environ 10 %","Environ 46 %, soit près de 76 milliards de dollars par an","Plus de 90 %"]'::jsonb,2,'Environ un quart des utilisateurs et 46 % des transactions, l''ordre de grandeur des marchés de la drogue aux États-Unis et en Europe. Des chiffres d''une période ancienne (jusqu''à 2017) : la part a baissé depuis.');
insert into public.questions values('s7',8,'Toujours selon « Sex, Drugs and Bitcoin », qu''est-ce qui fait baisser la part illégale de l''activité bitcoin ?','["La hausse des frais de transaction","L''intérêt du grand public et l''arrivée de cryptos plus opaques comme Monero","Le halving","Les ETF"]'::jsonb,1,'Plus Bitcoin devient grand public, plus la part légale grossit. Et les utilisateurs illégaux migrent vers Monero, Dash ou Zcash, plus difficiles à tracer.');
insert into public.questions values('s7',9,'« Coins for Bombs » : où se concentre le volume anormal de bitcoins avant les grands attentats ?','["Sur les exchanges régulés aux États-Unis","Sur les exchanges non régulés et les services de mixage","Sur les marchés de NFT","Sur Lightning"]'::jsonb,1,'+9,53 % de volume anormal cumulé avant l''attaque, puis −7,33 % après. Les fonds transitent par des plateformes sans KYC et des mixeurs pour être blanchis jusqu''aux opérateurs. Leçon : le registre public permet de détecter et même prédire certains financements illicites (un jour avant).');
insert into public.questions values('s7',10,'Hileman oppose l''or et Bitcoin face au risque quantique. Pourquoi ?','["L''or peut être piraté","L''or est protégé par les lois de la physique, Bitcoin par les mathématiques : une cryptographie cassée serait fatale à court terme","Bitcoin est déjà résistant au quantique","Ils sont exposés de la même façon"]'::jsonb,1,'D''où le débat sur des forks pour protéger les pièces de Satoshi ou les brûler. Beaucoup misent sur la cryptographie post-quantique, mais rien n''est garanti.');
insert into public.questions values('s7',11,'« Digital Gold and geopolitics » (Selmi et al.) : comment Bitcoin et l''or réagissent-ils au risque géopolitique ?','["Ils baissent toujours","Ils montent quand le risque est élevé, mais l''effet dépend du type de risque","Seul l''or réagit","Seul Bitcoin réagit"]'::jsonb,1,'Avec un indice composite de 7 risques (Chine-USA, guerres commerciales, Golfe, Europe, Corée du Nord, Russie-OTAN, terrorisme), les deux réagissent positivement en régime de risque élevé. Mais la volatilité et la spéculation empêchent Bitcoin d''être une valeur refuge établie.');
insert into public.questions values('s7',12,'« Flight to cryptos » : qu''arrive-t-il au trading crypto quand l''UE inclut explicitement les services crypto dans ses sanctions contre la Russie ?','["Il explose","Il ralentit, du moins sur les exchanges centralisés étudiés","Il ne change pas","Il passe entièrement sur Bitcoin"]'::jsonb,1,'Les sanctions mordent là où une plateforme garde les fonds (CEX). L''étude ne couvre pas les DEX, où ces sanctions s''appliquent beaucoup moins facilement.');
insert into public.questions values('s7',13,'Pourquoi les États-Unis ont-ils pris de l''avance sur la Chine pour adopter Bitcoin, selon Hileman ?','["La Chine n''a pas de mineurs","Un actif ouvert, décentralisé et détenu sans tiers convient mieux à une société ouverte ; il peut servir de « boulet de démolition » contre un système financier contrôlé","Parce que Bitcoin est une entreprise américaine","Parce que la Chine a déjà une CBDC en bitcoin"]'::jsonb,1,'En 2016, Hileman pensait que la Banque populaire de Chine pourrait l''adopter. Ce sont finalement les États-Unis qui ont annoncé une réserve en bitcoin, alimentée par les BTC saisis à des criminels.');
insert into public.questions values('s7',14,'Après l''invasion de l''Ukraine, quel comportement on-chain l''étude « Stablecoins as Digital Havens » observe-t-elle en Russie ?','["Du trading rapide d''USDT sur les exchanges","Plus d''USDT dans de petites adresses, de l''accumulation et des retraits hors des exchanges","Une fuite vers les NFT","Un décrochage d''USDT sous 0,90 $"]'::jsonb,1,'Les particuliers épargnent en dollar numérique et sortent leurs fonds des plateformes, par peur qu''elles soient touchées par les sanctions. USDT a tenu son ancrage malgré la demande. Contexte : environ 350 milliards de dollars (70 %) des actifs de la banque centrale russe gelés, banques exclues de SWIFT.');
insert into public.questions values('s7',15,'Quelle erreur Hileman attribue-t-il en partie à Hayek (« Denationalisation of Money ») ?','["Hayek croyait que seuls les États peuvent créer de la monnaie","Hayek pensait que la monnaie privée la plus stable gagnerait, alors que beaucoup préfèrent détenir ce qui peut monter","Hayek avait prédit l''or numérique","Hayek refusait toute concurrence monétaire"]'::jsonb,1,'Hayek a anticipé la concurrence des monnaies privées. Mais le leader, Bitcoin, est tout sauf stable : sa rareté et son potentiel de hausse l''avantagent face aux stablecoins.');
insert into public.questions values('s7',16,'Comment est construit l''indice d''incertitude crypto UCRY (Lucey et al.) ?','["À partir des prix des options","À partir de 726,9 millions d''articles de presse (LexisNexis), en deux volets : politique (Policy) et prix (Price)","À partir des votes des mineurs","À partir des comptes Twitter"]'::jsonb,1,'Il compte les articles qui associent crypto et incertitude. Incertitude n''est pas volatilité : elle bouge moins souvent, mais ses mouvements durent plus longtemps.');
insert into public.questions values('s7',17,'« Distrust or speculation? » (Auer, BRI) : pourquoi les Américains achètent-ils des cryptos ?','["Par méfiance envers les banques et le dollar","Surtout par spéculation : ils ne sont pas plus méfiants que la moyenne envers le cash ou les banques","Pour payer leurs courses","Pour échapper à l''impôt"]'::jsonb,1,'Les détenteurs sont plutôt jeunes, diplômés, natifs du numérique et masculins. Le récit « crypto contre le système » ne se vérifie pas dans les données américaines.');
insert into public.questions values('s7',18,'Que retient Hileman de l''histoire des monnaies alternatives (Wörgl, beenz, flooz…) ?','["Elles ont presque toutes réussi","La grande majorité meurt vite, rarement à cause des régulateurs","Elles ont toutes été interdites","Elles sont devenues des monnaies nationales"]'::jsonb,1,'Bitcoin fait figure d''exception par sa durée. Certaines ont été interdites, comme la monnaie fondante de Wörgl en Autriche (1932), mais la plupart s''éteignent d''elles-mêmes.');
insert into public.questions values('s7',19,'Quel moteur Hileman juge-t-il le plus prometteur pour faire de Bitcoin une monnaie ?','["Les cartes bancaires crypto","L''économie machine-à-machine : IA et robots ont besoin d''une monnaie numérique, programmable et sans gardien","Les distributeurs de billets","Le retour à l''étalon-or"]'::jsonb,1,'Comme on utilise l''euro en Europe, on utiliserait « la monnaie du royaume » des machines. Son usage pourrait ensuite déborder vers les humains, jusqu''aux salaires.');
insert into public.levels(id,ord,title,src) values('s8',8,'Tokenisation et stablecoins','Session 8 · support PDF, tutoriel RWA.xyz, cours préenregistré et Q&R avec Ripple') on conflict(id) do update set ord=excluded.ord,title=excluded.title,src=excluded.src;
insert into public.questions values('s8',0,'Qu''est-ce que la tokenisation ?','["Convertir des cryptos en euros","Créer sur la blockchain une représentation d''un actif réel ou financier qui n''y est pas né","Découper un bitcoin en satoshis","Miner un nouveau jeton"]'::jsonb,1,'Un dollar, une obligation ou un immeuble reçoit un jeton qui le représente sur la chaîne. Le jeton adossé au dollar reste l''exemple le plus courant.');
insert into public.questions values('s8',1,'Dans le schéma classique de la tokenisation, quelles sont les trois étapes ?','["Minage, validation, finalisation","Garde de l''actif par un dépositaire, émission du jeton, rachat contre l''actif","Achat, staking, revente","Audit, cotation, introduction en bourse"]'::jsonb,1,'Le dépositaire prend le contrôle de l''actif, émet le jeton, et peut le racheter à un taux fixe, souvent 1 pour 1.');
insert into public.questions values('s8',2,'Sur quel marché un détenteur revend-il ses jetons à un autre détenteur ?','["Le marché primaire","Le marché secondaire","Le marché monétaire","Le marché de gré à gré de la banque centrale"]'::jsonb,1,'Le marché primaire relie le dépositaire et le détenteur (émission, rachat). Les échanges entre détenteurs forment le marché secondaire.');
insert into public.questions values('s8',3,'Quel est le principal piège de la tokenisation d''un immeuble ?','["Le jeton ne peut pas être transféré","Le jeton vit sur un réseau décentralisé, mais l''immeuble dépend d''un dépositaire : on doit lui refaire confiance","La blockchain ne peut pas stocker de prix","Les frais de gas dépassent le prix de l''immeuble"]'::jsonb,1,'La centralisation revient par la porte de derrière. La blockchain prouve que tu as le jeton, pas que le dépositaire honorera ta part.');
insert into public.questions values('s8',4,'Pourquoi un actif tokenisé peut-il rester peu liquide ?','["Parce que les jetons expirent","Parce qu''il faut des acheteurs : marchés fragmentés, accès restreint et évaluation difficile gardent le marché mince","Parce que la blockchain limite les ventes à une par jour","Parce que les stablecoins sont interdits"]'::jsonb,1,'Rendre un actif échangeable ne crée pas d''acheteurs. Le FT décrit l''immobilier fractionné comme un marché naissant, de niche et en difficulté.');
insert into public.questions values('s8',5,'En 2026, quel est de loin le plus gros actif tokenisé ?','["Les bons du Trésor américain","L''immobilier","Les stablecoins, avec environ 302,9 milliards de dollars","L''or"]'::jsonb,2,'Hors stablecoins, les actifs réels tokenisés pèsent 38,8 milliards. Les stablecoins écrasent toutes les autres catégories.');
insert into public.questions values('s8',6,'Qu''est-ce que BUIDL ?','["Le stablecoin de Ripple","Le fonds tokenisé de bons du Trésor américain de BlackRock, réservé aux institutions","Un protocole de prêt DeFi","La CBDC chinoise"]'::jsonb,1,'Jeton à 1 $ qui verse un rendement, premier fonds tokenisé de Trésor à dépasser 1 milliard (mars 2025), environ 2,8 milliards en août 2026. Il passe par Securitize.');
insert into public.questions values('s8',7,'Pourquoi BUIDL ne compte-t-il que quelques dizaines de détenteurs ?','["Parce que son jeton coûte 1 million de dollars","Parce qu''il est permissionné : seuls des investisseurs institutionnels vérifiés peuvent y accéder","Parce qu''il vient d''être lancé","Parce qu''il est sur une blockchain privée sans portefeuilles"]'::jsonb,1,'Le tutoriel RWA.xyz le confirme : pour les bons du Trésor tokenisés, il faut en général être vérifié, d''où peu de détenteurs.');
insert into public.questions values('s8',8,'Quelle fonction de la monnaie une crypto volatile rate-t-elle d''abord ?','["La divisibilité","L''unité de compte : personne ne fixe ses prix dans une monnaie qui bouge sans cesse","La transportabilité","La résistance à la contrefaçon"]'::jsonb,1,'Les cryptos sont durables, divisibles, fongibles et infalsifiables. C''est la stabilité qui leur manque pour être une bonne monnaie.');
insert into public.questions values('s8',9,'Que garde stable un stablecoin adossé au dollar ?','["Son pouvoir d''achat","Son prix exprimé en dollars","Le prix du bitcoin","Le taux de la Fed"]'::jsonb,1,'Le dollar lui-même a perdu l''essentiel de son pouvoir d''achat au XXe siècle. La stabilité est relative.');
insert into public.questions values('s8',10,'Comment fonctionne USDT ?','["Il est surgaranti par de l''ETH","On dépose 1 $ chez Tether, qui émet 1 USDT, rachetable 1 $ à tout moment","Un algorithme crée et détruit un jeton action","Il est émis par la Fed"]'::jsonb,1,'Garantie exogène et centralisée : il faut croire que Tether détient les réserves et honorera les rachats.');
insert into public.questions values('s8',11,'Avec 150 $ d''ETH bloqués dans un coffre Maker, combien de DAI Alice peut-elle émettre au maximum dans l''exemple du cours ?','["150 DAI","100 DAI","300 DAI","50 DAI"]'::jsonb,1,'Le DAI est surgaranti : on bloque plus de valeur qu''on emprunte. C''est son inefficacité en capital.');
insert into public.questions values('s8',12,'Le « Jeudi noir » de mars 2020, que fait le DAI ?','["Il tombe à 0,50 $","Il passe au-dessus de 1 $","Il disparaît","Il reste parfaitement à 1 $"]'::jsonb,1,'L''ETH perd environ 50 % en un jour. Tout le monde veut du DAI (refuge, remboursements), mais en créer exige de bloquer de l''ETH effondré : pénurie, prix au-dessus de 1 $.');
insert into public.questions values('s8',13,'Quel était le défaut de conception du DAI révélé en mars 2020 ?','["Ses contrats avaient une faille","Son offre dépendait d''une garantie volatile et de l''envie de levier, pas de la demande de DAI","Il était garanti par des dollars","Il n''avait pas d''oracle"]'::jsonb,1,'Le DAI naît des emprunteurs qui veulent du levier, pas de ceux qui veulent le garder.');
insert into public.questions values('s8',14,'Un stablecoin algorithmique vaut 0,90 $. Que fait l''arbitragiste ?','["Il crée de nouveaux stablecoins","Il achète le stablecoin à 0,90 $ et le détruit contre 1 $ de jeton action : moins d''offre, le prix remonte","Il attend","Il le vend à découvert à la banque centrale"]'::jsonb,1,'À 1,10 $, il fait l''inverse : il détruit 1 $ de jeton action pour créer un stablecoin et le vendre 1,10 $.');
insert into public.questions values('s8',15,'Pourquoi UST et Luna se sont-ils effondrés ensemble en 2022 ?','["Une faille de sécurité a vidé les réserves en dollars","Pour défendre UST, le protocole a émis énormément de Luna, dont le prix s''est effondré : spirale","La SEC a interdit Terra","Les mineurs ont arrêté de valider"]'::jsonb,1,'Le mécanisme ne tient que si chacun croit que les deux jetons gardent de la valeur. Le jeton action est un pari sur l''écosystème.');
insert into public.questions values('s8',16,'Une CBDC de gros est destinée à qui ?','["Aux particuliers","Aux banques et institutions agréées, pour les règlements entre elles","Aux touristes étrangers","Aux mineurs"]'::jsonb,1,'De détail : les ménages. Universelle : aussi les étrangers.');
insert into public.questions values('s8',17,'En mai 2026, où en sont les CBDC dans le monde ?','["Aucun pays n''y travaille","146 pays en explorent une et 3 en ont lancé une","Tous les pays du G20 en ont lancé une","Seule la Chine y travaille"]'::jsonb,1,'Selon le CBDC Tracker de l''Atlantic Council. En 2023, 94 % des banques centrales interrogées par la BRI y travaillaient.');
insert into public.questions values('s8',18,'Pourquoi une CBDC peut-elle menacer les banques commerciales ?','["Elle supprime les billets","En crise, les épargnants peuvent vider leurs dépôts vers la monnaie la plus sûre en un clic : c''est la désintermédiation","Elle oblige les banques à miner","Elle interdit les prêts"]'::jsonb,1,'Parades : plafonds de détention, taux échelonnés, distribution par les banques, assurance des dépôts, prêt des dépôts CBDC aux banques.');
insert into public.questions values('s8',19,'Qu''est-ce qui distingue un dépôt tokenisé d''un stablecoin comme USDC ?','["Rien, ce sont des synonymes","Il est émis par une banque régulée et couvert par ses dépôts sous le droit bancaire","Il est émis par la banque centrale","Il est garanti par de l''ETH"]'::jsonb,1,'C''est un juste milieu entre CBDC de détail et stablecoin. USDC, lui, détient un mélange de réserves (liquidités, bons du Trésor) sous des règles variables.');
